import('/workspace/context-packet.js').then(({packContext}) => {
  const assert = (cond, msg) => { if (!cond) throw new Error('FAIL: ' + msg); };
  const e = packContext([], 0);
  assert(e.text === '' && e.bytes === 0 && e.included.length === 0 && e.omitted.length === 0, 'empty');
  assert(packContext([{id:'a',text:'x',priority:0,required:true}], 2**53-1).included.length === 1, 'max safe int');
  assert.throws(() => packContext([], 2**53), 'not safe int');
  assert.throws(() => packContext([], 0.5), 'float');
  assert.throws(() => packContext([], -1), 'negative');
  assert.throws(() => packContext({0:{id:'a',text:'',priority:0,required:false},length:1}, 10), 'sparse obj');
  assert(packContext([{id:'nul\u0000id',text:'t',priority:0,required:true}], 100).included[0] === 'nul\u0000id', 'nul id');
  assert.throws(() => packContext([{id:'a',text:'',priority:0,required:false,extra:1},{id:'a',text:'',priority:0,required:false}], 10), 'dup');
  assert.throws(() => packContext([{id:'A',text:'',priority:0,required:false},{id:'a',text:'',priority:0,required:false}], 10), 'case sensitive dup ok -> should NOT throw');
}).catch(err => { console.log('threw:', err.message); process.exit(1); });
"

