import {readFileSync, realpathSync} from 'node:fs';
import {pathToFileURL} from 'node:url';

function isNonNegativeSafeInteger(value) {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

function isSectionObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function assertSection(section, index) {
  if (!isSectionObject(section)) {
    throw new Error(`section at index ${index} must be a non-null, non-array object`);
  }
  const {id, text, priority, required} = section;
  if (typeof id !== 'string' || id.length === 0) {
    throw new Error(`section at index ${index} must have a nonempty string id`);
  }
  if (typeof text !== 'string') {
    throw new Error(`section "${id}" must have a string text`);
  }
  if (!isNonNegativeSafeInteger(priority)) {
    throw new Error(`section "${id}" must have a nonnegative safe integer priority`);
  }
  if (typeof required !== 'boolean') {
    throw new Error(`section "${id}" must have a boolean required`);
  }
}

export function packContext(sections, maxBytes) {
  if (!isNonNegativeSafeInteger(maxBytes)) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    throw new Error('sections must be an array');
  }
  const seenIds = new Set();
  for (let i = 0; i < sections.length; i++) {
    const section = sections[i];
    if (section === undefined) {
      throw new Error(`sections must be dense: missing entry at index ${i}`);
    }
    assertSection(section, i);
    const id = section.id;
    if (seenIds.has(id)) {
      throw new Error(`duplicate section id: ${id}`);
    }
    seenIds.add(id);
  }

  const requiredEntries = [];
  const optionalEntries = [];
  for (let i = 0; i < sections.length; i++) {
    const section = sections[i];
    const frame = '### ' + JSON.stringify(section.id) + '\n' + section.text + '\n';
    const entry = {
      id: section.id,
      frame,
      cost: Buffer.byteLength(frame, 'utf8'),
      index: i,
      priority: section.priority,
    };
    (section.required ? requiredEntries : optionalEntries).push(entry);
  }

  const requiredCost = requiredEntries.reduce((sum, entry) => sum + entry.cost, 0);
  if (requiredCost > maxBytes) {
    throw new Error('required sections exceed maxBytes');
  }

  let remaining = maxBytes - requiredCost;
  const orderedOptionals = [...optionalEntries].sort(
    (a, b) => b.priority - a.priority || a.index - b.index,
  );
  const includedEntries = [...requiredEntries];
  const includedIds = new Set();
  for (const entry of orderedOptionals) {
    if (entry.cost <= remaining) {
      remaining -= entry.cost;
      includedEntries.push(entry);
      includedIds.add(entry.id);
    }
  }

  return {
    text: includedEntries.map((entry) => entry.frame).join(''),
    bytes: includedEntries.reduce((sum, entry) => sum + entry.cost, 0),
    included: includedEntries.map((entry) => entry.id),
    omitted: optionalEntries.filter((entry) => !includedIds.has(entry.id)).map((entry) => entry.id),
  };
}

function runCli() {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    fail('usage: node context-packet.js INPUT_JSON_FILE (exactly one argument required)');
    return;
  }
  const file = args[0];
  let raw;
  try {
    raw = readFileSync(file, 'utf8');
  } catch (err) {
    fail(`cannot read input file: ${err.message}`);
    return;
  }
  let payload;
  try {
    payload = JSON.parse(raw);
  } catch (err) {
    fail(`invalid JSON: ${err.message}`);
    return;
  }
  if (!isSectionObject(payload)) {
    fail('input JSON must be an object with sections and maxBytes');
    return;
  }
  let result;
  try {
    result = packContext(payload.sections, payload.maxBytes);
  } catch (err) {
    fail(err.message);
    return;
  }
  process.stdout.write(JSON.stringify(result) + '\n');
}

function fail(message) {
  process.stderr.write(message + '\n');
  process.exitCode = 2;
}

function isCliEntry() {
  const entry = process.argv[1];
  if (typeof entry !== 'string' || entry === '') return false;
  try {
    return pathToFileURL(realpathSync(entry)).href === import.meta.url;
  } catch {
    return false;
  }
}

if (isCliEntry()) {
  runCli();
}

