--- starter/test/packet.test.js
+++ delivered/test/packet.test.js
@@ -0,0 +1,246 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import {spawnSync} from 'node:child_process';
+import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
+import {tmpdir} from 'node:os';
+import {join} from 'node:path';
+import {fileURLToPath, pathToFileURL} from 'node:url';
+import {packContext} from '../context-packet.js';
+
+const section = (id, text, priority = 0, required = false) => ({id, text, priority, required});
+const frameOf = (id, text) => '### ' + JSON.stringify(id) + '\n' + text + '\n';
+const costOf = (id, text) => Buffer.byteLength(frameOf(id, text), 'utf8');
+
+test('maxBytes must be a nonnegative safe integer', () => {
+  for (const bad of [-1, 1.5, NaN, Infinity, '10', null, undefined, {}, []]) {
+    assert.throws(() => packContext([], bad), Error);
+  }
+  assert.deepEqual(packContext([], 0), {text: '', bytes: 0, included: [], omitted: []});
+  assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER).bytes, 0);
+});
+
+test('sections must be a dense array of plain objects', () => {
+  for (const bad of [null, undefined, 42, 'x', {}, new Set()]) {
+    assert.throws(() => packContext(bad, 10), Error);
+  }
+  assert.throws(() => packContext(new Array(2), 10), Error);
+  assert.throws(() => packContext([undefined], 10), Error);
+  const sparse = [];
+  sparse[2] = section('a', 'a');
+  assert.throws(() => packContext(sparse, 10), Error);
+  for (const bad of [null, 42, 's', [], {}]) {
+    assert.throws(() => packContext([bad], 10), Error);
+  }
+  assert.throws(() => packContext([[section('a', 'a')]], 10), Error);
+  assert.deepEqual(packContext([], 5).included, []);
+});
+
+test('field validation is strict and uncoerced', () => {
+  const cases = [
+    [{text: 't', priority: 0, required: false}], // missing id
+    [{id: '', text: 't', priority: 0, required: false}],
+    [{id: 7, text: 't', priority: 0, required: false}],
+    [{id: null, text: 't', priority: 0, required: false}],
+    [{id: 'a', priority: 0, required: false}], // missing text
+    [{id: 'a', text: 3, priority: 0, required: false}],
+    [{id: 'a', text: null, priority: 0, required: false}],
+    [{id: 'a', text: 't', required: false}], // missing priority
+    [{id: 'a', text: 't', priority: -1, required: false}],
+    [{id: 'a', text: 't', priority: 1.5, required: false}],
+    [{id: 'a', text: 't', priority: Infinity, required: false}],
+    [{id: 'a', text: 't', priority: '5', required: false}],
+    [{id: 'a', text: 't', priority: NaN, required: false}],
+    [{id: 'a', text: 't', priority: 0}], // missing required
+    [{id: 'a', text: 't', priority: 0, required: 'yes'}],
+    [{id: 'a', text: 't', priority: 0, required: 1}],
+    [{id: 'a', text: 't', priority: 0, required: null}],
+  ];
+  for (const bad of cases) {
+    assert.throws(() => packContext(bad, 100), Error, JSON.stringify(bad));
+  }
+  assert.doesNotThrow(() => packContext([{id: 'a', text: 't', priority: 0, required: false, extra: 1}], 100));
+  assert.doesNotThrow(() => packContext([Object.assign(Object.create(null), {id: 'a', text: 't', priority: 0, required: false})], 100));
+});
+
+test('ids are unique exact strings; __proto__, spaces, unicode, NUL are valid', () => {
+  assert.throws(() => packContext([section('A', 'a'), section('A', 'b')], 100), Error);
+  assert.throws(() => packContext([section('x', 'a'), section('x', 'b', 1, true)], 0), Error);
+  const ok = packContext(
+    [
+      section('__proto__', 'p'),
+      section('  spaced  ', 's'),
+      section('uni\u0000code', 'n'),
+      section('A', 'a'),
+      section('a', 'b'),
+    ],
+    1000,
+  );
+  assert.deepEqual(ok.included, ['__proto__', '  spaced  ', 'uni\u0000code', 'A', 'a']);
+  assert.ok(ok.text.includes(frameOf('__proto__', 'p')));
+  assert.ok(ok.text.includes(frameOf('uni\u0000code', 'n')));
+});
+
+test('validation runs even when budget is zero or entries would be omitted', () => {
+  assert.throws(() => packContext([section('a', 'x'), section('a', 'y')], 0), Error);
+  assert.throws(() => packContext([section('a', 'x'), {id: 'b', text: 9, priority: 0, required: false}], 0), Error);
+  assert.throws(() => packContext([section('a', 'x', 0, true), section('b', 'y')], 0), Error);
+});
+
+test('frames are exact and bytes are UTF-8', () => {
+  const res = packContext([section('id"q', 'héllo\nworld', 0, true)], 1000);
+  assert.equal(res.text, '### "id\\"q"\nhéllo\nworld\n');
+  assert.equal(res.bytes, Buffer.byteLength(res.text, 'utf8'));
+  assert.equal(res.bytes, costOf('id"q', 'héllo\nworld'));
+  assert.deepEqual(res.included, ['id"q']);
+  assert.deepEqual(res.omitted, []);
+});
+
+test('required sections come first in input order; overflow throws', () => {
+  const sections = [section('opt', 'z', 99), section('r2', 'bb', 1, true), section('r1', 'a', 5, true)];
+  const reqCost = costOf('r2', 'bb') + costOf('r1', 'a');
+  const cost = reqCost + costOf('opt', 'z');
+  const res = packContext(sections, cost);
+  assert.equal(res.text, frameOf('r2', 'bb') + frameOf('r1', 'a') + frameOf('opt', 'z'));
+  assert.deepEqual(res.included, ['r2', 'r1', 'opt']);
+  assert.deepEqual(res.omitted, []);
+  assert.throws(() => packContext(sections, reqCost - 1), Error);
+  const tight = packContext(sections, reqCost);
+  assert.deepEqual(tight.included, ['r2', 'r1']);
+  assert.deepEqual(tight.omitted, ['opt']);
+  assert.equal(tight.bytes, reqCost);
+});
+
+test('optionals: priority desc, tie by input order, skip instead of stop', () => {
+  const sections = [
+    section('low', 'x', 1),
+    section('high', 'x', 5),
+    section('mid-a', 'x', 3),
+    section('mid-b', 'x', 3),
+    section('huge', 'x'.repeat(500), 4),
+  ];
+  const c = {
+    low: costOf('low', 'x'),
+    high: costOf('high', 'x'),
+    midA: costOf('mid-a', 'x'),
+    midB: costOf('mid-b', 'x'),
+    huge: costOf('huge', 'x'.repeat(500)),
+  };
+  const res = packContext(sections, c.low + c.high + c.midA + c.midB);
+  assert.deepEqual(res.included, ['high', 'mid-a', 'mid-b', 'low']);
+  assert.deepEqual(res.omitted, ['huge']);
+  assert.equal(res.bytes, c.low + c.high + c.midA + c.midB);
+  const tie = packContext(
+    [section('t2', 'y', 7), section('t1', 'y', 7), section('t0', 'y', 8)],
+    costOf('t0', 'y') + costOf('t1', 'y') + costOf('t2', 'y'),
+  );
+  assert.deepEqual(tie.included, ['t0', 't2', 't1']);
+  const skip = packContext(sections, c.high + c.midA);
+  assert.deepEqual(skip.included, ['high', 'mid-a']);
+  assert.deepEqual(skip.omitted, ['low', 'mid-b', 'huge']);
+});
+
+test('omitted ids are reported in input order', () => {
+  const sections = [section('a', 'x', 1), section('b', 'x', 9), section('c', 'x', 5), section('d', 'x', 9)];
+  const res = packContext(sections, costOf('x', 'x') * 2);
+  assert.deepEqual(res.included, ['b', 'd']);
+  assert.deepEqual(res.omitted, ['a', 'c']);
+});
+
+test('input is not mutated', () => {
+  const sections = [
+    {id: 'a', text: 't', priority: 2, required: false, note: {deep: [1, 2]}},
+    section('b', 'u', 0, true),
+  ];
+  const snapshot = JSON.stringify(sections);
+  packContext(sections, 1000);
+  assert.equal(JSON.stringify(sections), snapshot);
+  assert.equal(Object.keys(sections[0]).length, 5);
+});
+
+const CLI = fileURLToPath(new URL('../context-packet.js', import.meta.url));
+
+function runCli(args) {
+  return spawnSync(process.execPath, [CLI, ...args], {encoding: 'utf8'});
+}
+
+test('CLI success prints exactly one JSON line and exits 0', () => {
+  const dir = mkdtempSync(join(tmpdir(), 'context-packet-'));
+  try {
+    const file = join(dir, 'input.json');
+    writeFileSync(file, JSON.stringify({
+      extra: true,
+      sections: [section('s1', 'one', 1), section('s2', 'two', 2, true)],
+      maxBytes: 10000,
+    }), 'utf8');
+    const res = runCli([file]);
+    assert.equal(res.status, 0);
+    assert.equal(res.stderr, '');
+    const lines = res.stdout.split('\n');
+    assert.deepEqual(lines.slice(-1), ['']);
+    assert.equal(lines.length, 2);
+    const parsed = JSON.parse(res.stdout);
+    assert.deepEqual(Object.keys(parsed), ['text', 'bytes', 'included', 'omitted']);
+    assert.equal(parsed.text, frameOf('s2', 'two') + frameOf('s1', 'one'));
+    assert.equal(parsed.bytes, parsed.text.length);
+    assert.deepEqual(parsed.included, ['s2', 's1']);
+    assert.deepEqual(parsed.omitted, []);
+  } finally {
+    rmSync(dir, {recursive: true, force: true});
+  }
+});
+
+test('CLI empty sections with zero budget succeeds', () => {
+  const dir = mkdtempSync(join(tmpdir(), 'context-packet-'));
+  try {
+    const file = join(dir, 'empty.json');
+    writeFileSync(file, '{"sections":[],"maxBytes":0}', 'utf8');
+    const res = runCli([file]);
+    assert.equal(res.status, 0);
+    assert.equal(res.stderr, '');
+    assert.equal(res.stdout, JSON.stringify({text: '', bytes: 0, included: [], omitted: []}) + '\n');
+  } finally {
+    rmSync(dir, {recursive: true, force: true});
+  }
+});
+
+test('CLI failure modes exit 2 with stderr and no stdout', () => {
+  const dir = mkdtempSync(join(tmpdir(), 'context-packet-'));
+  try {
+    const write = (name, content) => {
+      const file = join(dir, name);
+      writeFileSync(file, content, 'utf8');
+      return file;
+    };
+    const cases = [
+      [], // no args
+      [write('ok.json', '{"sections":[],"maxBytes":0}'), 'extra-arg'], // two args
+      [join(dir, 'missing.json')], // unreadable file
+      [write('bad.json', '{not json')], // invalid JSON
+      [write('array.json', '[1,2,3]')], // top-level not an object
+      [write('string.json', '"hi"')], // top-level not an object
+      [write('maxstr.json', '{"sections":[],"maxBytes":"10"}')], // API input invalid
+      [write('sparse.json', '{"sections":[null],"maxBytes":10}')], // API input invalid
+      [write('dup.json', '{"sections":[{"id":"a","text":"t","priority":0,"required":false},{"id":"a","text":"t","priority":0,"required":false}],"maxBytes":10}')],
+      [write('overflow.json', '{"sections":[{"id":"a","text":"t","priority":0,"required":true}],"maxBytes":0}')],
+    ];
+    for (const args of cases) {
+      const res = runCli(args);
+      assert.equal(res.status, 2, JSON.stringify(args));
+      assert.ok(res.stderr.length > 0, 'stderr must be nonempty for ' + JSON.stringify(args));
+      assert.equal(res.stdout, '', 'stdout must be empty for ' + JSON.stringify(args));
+    }
+  } finally {
+    rmSync(dir, {recursive: true, force: true});
+  }
+});
+
+test('importing the module does not run the CLI', () => {
