+    process.execPath,
+    ['-e', `import(${JSON.stringify(pathToFileURL(CLI).href)}).then(m => console.log('imported', typeof m.packContext))`],
+    {encoding: 'utf8'},
+  );
+  assert.equal(res.status, 0);
+  assert.equal(res.stderr, '');
+  assert.equal(res.stdout.trim(), 'imported function');
+});

